import React from 'react';
import '../../App.css';
import Card from '../Card';
import Footer from '../Footer';

function Buy() {
    return (
        <>            
            <h1 className='buy'>Give us money!!!!!!</h1>
            <h2 className='buy'></h2>

            <Card />
            <Footer />
        </>
    );
}

export default Buy;
